_CORE_SRC = '# Exact action format: {"moves": {unit_id: to_node, ...}}\n# Payout: served_p = capacity_p * stock / max(total_capacity, stock).\n# Cost: 3.0 per truck and 1.5 per scooter not on its own player\'s base\n# after this turn\'s moves; couriers on their own base cost nothing.\nimport heapq\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\n\nN_TURNS = 60\nCAPACITY = {"truck": 8, "scooter": 3}\nCOST = {"truck": 3.0, "scooter": 1.5}\nSPEED = {"truck": 1, "scooter": 2}\n\n\ndef served(own, opponent, stock):\n    """The exact service formula, with the empty-node case handled explicitly."""\n    denominator = max(own + opponent, stock)\n    if denominator <= 0:\n        return 0.0\n    return own * stock / denominator\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    for a, b in edges:\n        adjacency[a].append(b)\n        adjacency[b].append(a)\n    for neighbors in adjacency:\n        neighbors.sort()\n\n    distances = []\n    for source in range(n):\n        row = [-1] * n\n        row[source] = 0\n        queue = deque([source])\n        while queue:\n            node = queue.popleft()\n            for neighbor in adjacency[node]:\n                if row[neighbor] < 0:\n                    row[neighbor] = row[node] + 1\n                    queue.append(neighbor)\n        distances.append(row)\n\n    # A scooter may use either of its two edges without affecting intermediate nodes.\n    steps = {}\n    for speed in (1, 2):\n        table = [[0] * n for _ in range(n)]\n        for source in range(n):\n            for target in range(n):\n                choices = [\n                    v for v in range(n)\n                    if 0 <= distances[source][v] <= speed\n                ]\n                table[source][target] = min(\n                    choices,\n                    key=lambda v: (\n                        distances[v][target],\n                        distances[source][v],\n                        v,\n                    ),\n                )\n        steps[speed] = table\n    return distances, steps\n\n\ndef legal_action(units, targets, distances, steps, n):\n    """Validate each move against its courier\'s start-of-turn position."""\n    moves = {}\n    for uid in sorted(units):\n        kind, origin = units[uid]\n        target = targets.get(uid, origin)\n        if kind not in SPEED or not isinstance(target, int):\n            continue\n        if not 0 <= target < n:\n            continue\n        destination = int(steps[SPEED[kind]][origin][target])\n        if (\n            0 <= destination < n\n            and 0 <= distances[origin][destination] <= SPEED[kind]\n            and destination != origin\n        ):\n            moves[str(uid)] = int(destination)\n    return {"moves": moves}\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_key = None\n        self.distances = None\n        self.steps = None\n        self.targets = {}\n        self.bad_reports = 0\n\n    def _plan(self, obs, deadline):\n        n = obs["n_nodes"]\n        home = obs["player_base"]\n        units = obs.get("player_units", {})\n        remaining = max(0, N_TURNS - int(obs.get("turn", 0)))\n        if remaining == 0 or not units:\n            return {}\n\n        # No external demand forecast exists in Gamma. Forecast its stock exactly\n        # under each candidate stationary-target plan, including regeneration.\n        horizon = min(6, remaining)\n        weights = [0.94 ** t for t in range(horizon)]\n        stock = obs["stock"]\n        maximum = obs["stock_max"]\n        regen = obs["regen"]\n        opponent = [0] * n\n        for kind, node in obs.get("opponent_units", {}).values():\n            opponent[node] += CAPACITY[kind]\n\n        capacity = [[0] * horizon for _ in range(n)]\n        targets = {}\n        paths = {}\n        path_cache = {}\n\n        def trajectory(uid, target):\n            key = (uid, target)\n            cached = path_cache.get(key)\n            if cached is not None:\n                return cached\n            kind, position = units[uid]\n            step = self.steps[SPEED[kind]]\n            path = []\n            for _ in range(horizon):\n                position = step[position][target]\n                path.append(position)\n            path_cache[key] = path\n            return path\n\n        def node_value(node):\n            available = float(stock[node])\n            other = opponent[node]\n            value = 0.0\n            for t in range(horizon):\n                own = capacity[node][t]\n                mine = served(own, other, available)\n                theirs = served(other, own, available)\n                value += weights[t] * (mine - theirs)\n                available = round(\n                    min(maximum[node], available - mine - theirs + regen[node]),\n                    2,\n                )\n            return value\n\n        def travel_cost(uid, path):\n            kind = units[uid][0]\n            cost = COST[kind]\n            total = sum(weights[t] * cost for t, v in enumerate(path) if v != home)\n            # Beyond the forecast, account conservatively for getting home.\n            # There is no reason to reserve return costs after the game ends.\n            if remaining > horizon:\n                distance = self.distances[path[-1]][home]\n                turns = (distance + SPEED[kind] - 1) // SPEED[kind]\n                unpaid = min(max(0, turns - 1), remaining - horizon)\n                total += weights[-1] * 0.65 * cost * unpaid\n            return total\n\n        # Warm-start with sticky destinations. All units, including those still\n        # travelling, are counted at their exact predicted arrival times.\n        for uid in sorted(units):\n            target = self.targets.get(uid, home)\n            if not 0 <= target < n:\n                target = home\n            targets[uid] = target\n            path = trajectory(uid, target)\n            paths[uid] = path\n            cap = CAPACITY[units[uid][0]]\n            for t, node in enumerate(path):\n                capacity[node][t] += cap\n\n        values = [node_value(v) for v in range(n)]\n        order = sorted(\n            units,\n            key=lambda uid: (\n                -CAPACITY[units[uid][0]],\n                self.distances[units[uid][1]][home],\n                uid,\n            ),\n        )\n\n        # Coordinate marginal allocation accommodates heterogeneous couriers.\n        # Each heap contains exact incremental forecast values for this unit.\n        # Further sweeps let scooters replace trucks where only regen remains.\n        for sweep in range(3):\n            changed = False\n            sequence = order if sweep != 1 else list(reversed(order))\n            for uid in sequence:\n                if time.perf_counter() >= deadline:\n                    return targets\n                kind, origin = units[uid]\n                cap = CAPACITY[kind]\n                old_path = paths[uid]\n                affected_old = sorted(set(old_path))\n                for t, node in enumerate(old_path):\n                    capacity[node][t] -= cap\n                for node in affected_old:\n                    values[node] = node_value(node)\n\n                candidates = []\n                old_target = targets[uid]\n                for target in range(n):\n                    if time.perf_counter() >= deadline:\n                        break\n                    path = trajectory(uid, target)\n                    affected = sorted(set(path))\n                    before = sum(values[v] for v in affected)\n                    for t, node in enumerate(path):\n                        capacity[node][t] += cap\n                    after = sum(node_value(v) for v in affected)\n                    for t, node in enumerate(path):\n                        capacity[node][t] -= cap\n\n                    gain = after - before - travel_cost(uid, path)\n                    # Clear-margin hysteresis prevents marginal retargeting.\n                    if target == old_target:\n                        gain += 0.32\n                    if target == origin:\n                        gain += 0.06\n                    heapq.heappush(candidates, (-gain, target))\n\n                # If interrupted, the previous target is always a legal fallback.\n                target = heapq.heappop(candidates)[1] if candidates else old_target\n                path = trajectory(uid, target)\n                targets[uid] = target\n                paths[uid] = path\n                for t, node in enumerate(path):\n                    capacity[node][t] += cap\n                for node in sorted(set(path)):\n                    values[node] = node_value(node)\n                changed = changed or target != old_target\n            if not changed:\n                break\n        return targets\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.58 * TIME_BUDGET)\n        n = int(obs["n_nodes"])\n        key = (n, tuple(tuple(edge) for edge in obs.get("edges", [])))\n        if self.map_key != key:\n            self.distances, self.steps = preprocess_map(n, obs.get("edges", []))\n            self.map_key = key\n            self.targets = {}\n\n        if (\n            not obs.get("action_format_correct_last_turn", True)\n            or obs.get("n_invalid_actions_last_turn", 0) > 0\n        ):\n            self.bad_reports += 1\n\n        units = obs.get("player_units", {})\n        if self.bad_reports >= 2:\n            # Conservative recovery uses only direct, validated return-home moves.\n            targets = {uid: int(obs["player_base"]) for uid in units}\n        else:\n            targets = self._plan(obs, deadline)\n\n        action = legal_action(\n            units, targets, self.distances, self.steps, n\n        )\n        self.targets = dict(targets)\n        return action\n'
